<?php
require_once 'config/config.php';$u=require_login();$s=db()->prepare("SELECT b.*,r.room_number,rt.name type_name,p.status payment_status,p.transaction_id FROM bookings b JOIN rooms r ON r.id=b.room_id JOIN room_types rt ON rt.id=r.room_type_id LEFT JOIN payments p ON p.booking_id=b.id WHERE b.user_id=? ORDER BY b.created_at DESC");$s->execute([$u['id']]);$rows=$s->fetchAll();$title='My Bookings | '.APP_NAME;require 'partials_header.php';?>
<div class="page"><div class="container"><h1>My Bookings</h1><div class="panel table-wrap"><table class="table"><tr><th>Booking</th><th>Room</th><th>Dates</th><th>Total</th><th>Status</th><th>Payment</th><th>Action</th></tr><?php foreach($rows as $b): ?><tr><td><?=e($b['booking_code'])?></td><td><?=e($b['type_name'])?> #<?=e($b['room_number'])?></td><td><?=e($b['check_in'])?><br><?=e($b['check_out'])?></td><td>NPR <?=number_format((float)$b['total_amount'])?></td><td><span class="badge <?=e($b['status'])?>"><?=e($b['status'])?></span></td><td><span class="badge <?=e($b['payment_status']??'pending')?>"><?=e($b['payment_status']??'pending')?></span></td><td><?php if($b['status']==='confirmed'): ?><a class="btn small" href="cancel.php?id=<?=$b['id']?>">Cancel</a><?php endif;?></td></tr><?php endforeach;?></table></div></div></div><?php require 'partials_footer.php'; ?>
